(()=>{'use strict';const font='"BIZ UDPGothic","Yu Gothic",Meiryo,sans-serif';
const data={rbbb:{title:'右脚ブロック（RBBB）',left:[['心電図の観察点',['V1の終末の上向きR′','V6の幅広い終末S波']],['QRSの幅',['心室全体の興奮に時間がかかる','成人の完全型は120 ms以上']],['波形と機序の対応',['遅れて興奮する右室の影響が','QRSの終わりに現れます']]],right:[['① 右脚で伝導が遮断',['×印が右脚の遮断部位','右脚から右室へ直接伝わらない']],['② 左脚から左室へ伝導',['画面右の左室が先に興奮','左脚側の伝導は保たれます']],['③ 心筋を介して右室へ',['画面左の右室が遅れて興奮','黄色：通常、水色：遅れた興奮']]],notes:[['右室の遅れとQRS終末','右脚ブロック（RBBB）では、右脚を通る伝導が障害されます。この例は左脚から左室が先に興奮し、心筋を介して右室へ遅れて広がります。遅い右室興奮がQRSの終末に加わり、V1の上向きR′とV6の幅広い終末S波に対応します。'],['2誘導の比較','R′（アール・プライム）は、同じQRS内の後から現れる上向きの波です。成人の完全右脚ブロックはQRS幅120 ms以上と特徴的な形を合わせて評価します。V1は右室だけ、V6は左室だけを記録しているわけではありません。']]},lbbb:{notes:[['左室の遅れと幅広いQRS','左脚ブロック（LBBB）では、右脚から右室側へ伝わった興奮が、心筋を介して左室へ遅れて広がります。心室全体の興奮に時間がかかるためQRSが広くなり、この例ではV1は下向きの波が主体（陰性優位）、V6は幅広い上向きのR波になります。'],['興奮・収縮とST–T','図の光は電気的な興奮を示し、収縮はその後に起こります。QRSの終わりまで続く左室の興奮と幅広いQRSを対応させます。興奮の順序が変わると回復過程にも影響し、QRSの主な向きと反対方向のST–T変化が現れることがあります。']]}};
function text(ctx,s,x,y,size=25,bold=false){ctx.font=(bold?'700 ':'400 ')+size+'px '+font;ctx.fillStyle='#253746';ctx.fillText(s,x,y);}
let cache,cacheCtx,lastCtx;
function composeRbbb(){if(!lastCtx||!cache)return;const ctx=lastCtx;ctx.save();ctx.fillStyle='#F8FAFC';ctx.fillRect(0,0,1808,1088);ctx.drawImage(cache,520,0);if(window.bundleAnnotationsVisible!==false){const e=data.rbbb;for(const[x,sections,title]of[[35,e.left,e.title],[1335,e.right,'心臓で起こること']]){ctx.fillStyle='#fff';ctx.strokeStyle='#cbd5e1';ctx.lineWidth=2;ctx.fillRect(x,65,430,945);ctx.strokeRect(x,65,430,945);text(ctx,title,x+20,125,32,true);let y=245;for(const[h,lines]of sections){text(ctx,h,x+20,y,27,true);lines.forEach((s,i)=>text(ctx,s,x+20,y+55+i*48));y+=226;}}}text(ctx,'V1・V6：同じ拍の2誘導',28,1071,30,true);ctx.restore();}
window.relayoutRbbb=(ctx,canvas)=>{if(!cache){cache=document.createElement('canvas');cache.width=768;cache.height=1088;cacheCtx=cache.getContext('2d');}cacheCtx.clearRect(0,0,768,1088);cacheCtx.drawImage(canvas,176,0,768,1088,0,0,768,1088);lastCtx=ctx;composeRbbb();};
window.paintBundleLbbbFrame=(ctx,source,canvas)=>{ctx.save();ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,35,235,720,1020,35,0,720,1020);ctx.drawImage(source,790,385,990,700,800,180,990,700);text(ctx,'V1・V6：同じ拍の2誘導',800,65,34,true);text(ctx,'V1：下向きが主体 ／ V6：幅広いR波',800,125,29);text(ctx,'×印：左脚の遮断部位',800,165,25);text(ctx,'右室側から心筋を介して、左室へ遅れて伝導',800,950,28,true);text(ctx,'光は電気的な興奮、収縮はその後の動きです',800,1005,27);ctx.restore();};
document.addEventListener('DOMContentLoaded',()=>{const id=location.pathname.split('/').pop().replace(/\.html$/,''),box=document.createElement('aside');box.className='category-bundle-notes';box.setAttribute('aria-label','図と波形の固定解説');for(const[h,body]of data[id].notes){const p=document.createElement('p'),strong=document.createElement('strong');strong.textContent=h;p.append(strong,document.createTextNode(body));box.append(p);}window.LearnerDiagram.shell.querySelector('.diagram-tools').before(box);if(id==='rbbb'){const label=document.createElement('label');label.innerHTML='<input id="rbbb-label-toggle" type="checkbox" checked>注釈を表示';document.querySelector('nav.controls').append(label);label.querySelector('input').onchange=e=>{window.bundleAnnotationsVisible=e.target.checked;composeRbbb();};}document.documentElement.setAttribute('data-category-ready','true');});
})();


